import React from 'react';
import { Link } from 'react-router-dom';
import { Shield, Lock, Sparkles } from 'lucide-react';

const AuthLayout = ({ children, title, subtitle, type = 'login' }) => {
  const features = [
    {
      icon: <Shield className="text-primary-500" size={20} />,
      text: 'Authentification sécurisée'
    },
    {
      icon: <Sparkles className="text-secondary-500" size={20} />,
      text: 'Interface moderne'
    },
    {
      icon: <Lock className="text-accent-500" size={20} />,
      text: 'Protection des données'
    }
  ];

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-neutral-50 via-white to-primary-50 dark:from-neutral-950 dark:via-neutral-900 dark:to-primary-950/20 p-4">
      <div className="w-full max-w-6xl">
        <div className="flex flex-col lg:flex-row rounded-2xl overflow-hidden shadow-2xl">
          {/* Section gauche - Formulaire */}
          <div className="lg:w-1/2 p-8 md:p-12 bg-white dark:bg-neutral-900">
            <div className="max-w-md mx-auto">
              {/* Logo */}
              <div className="mb-8">
                <Link to="/" className="flex items-center space-x-2">
                  <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary-500 to-secondary-500 flex items-center justify-center">
                    <Lock size={24} className="text-white" />
                  </div>
                  <h1 className="text-2xl font-bold text-neutral-900 dark:text-white">
                    Secure<span className="text-primary-600 dark:text-primary-400">Auth</span>
                  </h1>
                </Link>
              </div>

              {/* En-tête */}
              <div className="mb-8">
                <h2 className="text-3xl font-bold text-neutral-900 dark:text-white mb-2">
                  {title}
                </h2>
                <p className="text-neutral-600 dark:text-neutral-400">
                  {subtitle}
                </p>
              </div>

              {/* Formulaire */}
              {children}

              {/* Lien entre login/register */}
              <div className="mt-8 text-center">
                <p className="text-neutral-600 dark:text-neutral-400">
                  {type === 'login' ? "Vous n'avez pas de compte ? " : "Vous avez déjà un compte ? "}
                  <Link 
                    to={type === 'login' ? '/register' : '/login'} 
                    className="text-primary-600 dark:text-primary-400 font-semibold hover:underline"
                  >
                    {type === 'login' ? "S'inscrire" : "Se connecter"}
                  </Link>
                </p>
              </div>
            </div>
          </div>

          {/* Section droite - Illustration */}
          <div className="lg:w-1/2 bg-gradient-to-br from-primary-500 via-primary-600 to-secondary-600 p-8 md:p-12 relative overflow-hidden hidden lg:block">
            <div className="relative z-10 h-full flex flex-col justify-center text-white">
              <div className="max-w-md mx-auto">
                <div className="mb-8">
                  <div className="inline-flex p-3 rounded-xl bg-white/10 backdrop-blur-sm mb-4">
                    <Lock size={32} />
                  </div>
                  <h3 className="text-3xl font-bold mb-4">
                    Sécurité & Confidentialité
                  </h3>
                  <p className="text-primary-100">
                    Votre sécurité est notre priorité. Nous utilisons le chiffrement de pointe pour protéger vos données.
                  </p>
                </div>

                {/* Features list */}
                <div className="space-y-4 mb-8">
                  {features.map((feature, index) => (
                    <div key={index} className="flex items-center space-x-3">
                      <div className="p-2 rounded-lg bg-white/10">
                        {feature.icon}
                      </div>
                      <span className="font-medium">{feature.text}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AuthLayout;
